10: static struct pcm_ring ring, independent;
11: static short input[PCM_RING_SAMPLES], output[PCM_RING_SAMPLES + 1];
12: enum { STREAM_SAMPLES = PCM_RING_SAMPLES * 32 };
13: 
14: static short sample(unsigned int index)
15: {
16: 	return (short) ((index ^ (index >> 15) ^ ((index * 1103515245u) >> 16)) & 0x7fffu);
17: }
18: 
19: static void boundaries(void)
20: {
21: 	const unsigned int starts[] = { 0, PCM_RING_SAMPLES - 3, INT_MAX - 2u, UINT_MAX - 2u };
22: 	for (unsigned int i = 0; i < PCM_RING_SAMPLES; ++i) input[i] = sample(i);
23: 
24: 	for (unsigned int test = 0; test < sizeof(starts) / sizeof(starts[0]); ++test) {
25: 		pcm_ring_reset(&ring);
26: 		ring.write_position = ring.read_position = (int) starts[test];
27: 		output[0] = -1;
28: 		assert(pcm_ring_read(&ring, output, 1) == 0 && output[0] == -1);
29: 		pcm_ring_write(&ring, input, PCM_RING_SAMPLES);
30: 		assert(pcm_ring_available(&ring) == PCM_RING_SAMPLES);
31: 		output[PCM_RING_SAMPLES] = -1;
32: 		assert(pcm_ring_read(&ring, output, PCM_RING_SAMPLES + 1) == PCM_RING_SAMPLES);
33: 		assert(memcmp(input, output, sizeof(input)) == 0 && output[PCM_RING_SAMPLES] == -1);
34: 		assert(pcm_ring_available(&ring) == 0);
35: 
36: 		pcm_ring_write(&ring, input, 7);
37: 		assert(pcm_ring_read(&ring, output, 3) == 3);
38: 		assert(pcm_ring_available(&ring) == 4 && memcmp(input, output, 3 * sizeof(short)) == 0);
39: 		output[4] = -1;
40: 		assert(pcm_ring_read(&ring, output, 6) == 4);
41: 		assert(memcmp(input + 3, output, 4 * sizeof(short)) == 0 && output[4] == -1);
42: 		pcm_ring_write(&ring, input, 7);
43: 		int published = ring.write_position;
44: 		pcm_ring_discard(&ring);
45: 		assert(pcm_ring_available(&ring) == 0 && ring.write_position == published);
46: 		pcm_ring_write(&ring, input + 7, 5);
47: 		assert(pcm_ring_read(&ring, output, 5) == 5 && memcmp(input + 7, output, 5 * sizeof(short)) == 0);
48: 		pcm_ring_write(&ring, input, 7);
49: 		pcm_ring_reset(&ring);
50: 		assert(ring.write_position == 0 && ring.read_position == 0 && pcm_ring_read(&ring, output, 1) == 0);
51: 	}
52: 	pcm_ring_write(&independent, input, 7);
53: 	pcm_ring_write(&ring, input + 7, 3);
54: 	pcm_ring_reset(&ring);
55: 	assert(pcm_ring_read(&independent, output, 7) == 7 && memcmp(input, output, 7 * sizeof(short)) == 0);
56: }
