58: static void *produce(void *unused)
59: {
60: 	(void) unused;
61: 	short chunk[4093];
62: 	for (unsigned int sent = 0; sent < STREAM_SAMPLES;) {
63: 		unsigned int count = 1 + sent % 4093;
64: 		if (count > STREAM_SAMPLES - sent) count = STREAM_SAMPLES - sent;
65: 		if (PCM_RING_SAMPLES - pcm_ring_available(&ring) < count) {
66: 			sched_yield();
67: 			continue;
68: 		}
69: 		for (unsigned int i = 0; i < count; ++i) chunk[i] = sample(sent + i);
70: 		pcm_ring_write(&ring, chunk, (int) count);
71: 		sent += count;
72: 	}
73: 	return NULL;
74: }
75: 
76: static void concurrent_stream(void)
77: {
78: 	pthread_t producer;
79: 	short chunk[997];
80: 	pcm_ring_reset(&ring);
81: 	/* Cross both array and 32-bit cursor boundaries with a live producer */
82: 	ring.write_position = ring.read_position = (int) (UINT_MAX - PCM_RING_SAMPLES);
83: 	assert(pthread_create(&producer, NULL, produce, NULL) == 0);
84: 	for (unsigned int received = 0; received < STREAM_SAMPLES;) {
85: 		int count = pcm_ring_read(&ring, chunk, 997);
86: 		if (!count) sched_yield();
87: 		for (int i = 0; i < count; ++i) assert(chunk[i] == sample(received + (unsigned int) i));
88: 		received += (unsigned int) count;
89: 	}
90: 	assert(pthread_join(producer, NULL) == 0);
91: 	assert(pcm_ring_available(&ring) == 0 && pcm_ring_read(&ring, chunk, 997) == 0);
92: }
