15: /* Both producer and consumer must be quiescent during reset */
16: static inline void pcm_ring_reset(struct pcm_ring *ring)
17: {
18: 	__atomic_store_n(&ring->write_position, 0, __ATOMIC_SEQ_CST);
19: 	__atomic_store_n(&ring->read_position, 0, __ATOMIC_SEQ_CST);
20: }
21: 
22: /* Reader-side discard leaves the producer's monotonic cursor intact */
23: static inline void pcm_ring_discard(struct pcm_ring *ring)
24: {
25: 	int write_position = __atomic_load_n(&ring->write_position, __ATOMIC_ACQUIRE);
26: 	__atomic_store_n(&ring->read_position, write_position, __ATOMIC_RELEASE);
27: }
28: 
29: /* The sole producer must check space with available() before writing count samples */
30: static inline void pcm_ring_write(struct pcm_ring *ring, const short *data, int count)
31: {
32: 	unsigned int wpos = (unsigned int) __atomic_load_n(&ring->write_position, __ATOMIC_RELAXED);
33: 	unsigned int idx = wpos & (PCM_RING_SAMPLES - 1);
34: 	int first = PCM_RING_SAMPLES - (int) idx;
35: 	if (first > count) first = count;
36: 	memcpy(&ring->samples[idx], data, first * sizeof(short));
37: 	if (count > first)
38: 		memcpy(&ring->samples[0], data + first, (count - first) * sizeof(short));
39: 	__atomic_store_n(&ring->write_position, (int) (wpos + (unsigned int) count), __ATOMIC_RELEASE);
40: }
41: 
42: /* The sole consumer receives at most count samples; an empty ring returns zero */
43: static inline int pcm_ring_read(struct pcm_ring *ring, short *out, int count)
44: {
45: 	unsigned int wpos = (unsigned int) __atomic_load_n(&ring->write_position, __ATOMIC_ACQUIRE);
46: 	unsigned int rpos = (unsigned int) __atomic_load_n(&ring->read_position, __ATOMIC_RELAXED);
47: 	unsigned int avail = wpos - rpos;
48: 	if ((int) avail < count) count = (int) avail;
49: 	if (count <= 0) return 0;
50: 	unsigned int idx = rpos & (PCM_RING_SAMPLES - 1);
51: 	int first = PCM_RING_SAMPLES - (int) idx;
52: 	if (first > count) first = count;
53: 	memcpy(out, &ring->samples[idx], first * sizeof(short));
54: 	if (count > first)
55: 		memcpy(out + first, &ring->samples[0], (count - first) * sizeof(short));
56: 	__atomic_store_n(&ring->read_position, (int) (rpos + (unsigned int) count), __ATOMIC_RELEASE);
57: 	return count;
58: }
59: 
60: /* Producer/consumer callers use their own cursor and acquire the other cursor */
61: static inline unsigned int pcm_ring_available(const struct pcm_ring *ring)
62: {
63: 	return (unsigned int) __atomic_load_n(&ring->write_position, __ATOMIC_ACQUIRE) -
64: 	       (unsigned int) __atomic_load_n(&ring->read_position, __ATOMIC_ACQUIRE);
65: }

